import os
import yaml


def get_yaml_ue_config():
    """
    Get UE configuration from yaml file.
    :return: UE config if exists, else None
    """
    ue_config_abs_path = os.getenv("ABSTRACT_LIB_CONFIG")
    ue_config = None
    if ue_config_abs_path:
        with open(ue_config_abs_path) as ta_ue_config:
            ue_config = yaml.safe_load(ta_ue_config)
    return ue_config


def get_ue_configuration(ue_id=0, ues_config=None):
    if ues_config is None:
        ues_config = get_yaml_ue_config()

    ue_index = 0
    for ue_pool in ues_config['UE_POOLS']:
        inline_config = ues_config['UE_POOLS'][ue_pool]['inline_config']
        for ue_name in inline_config.keys():
            if ue_index == ue_id:
                return inline_config[ue_name]['CONSTRUCTOR_PARAMETERS']['configuration']
            ue_index = ue_index + 1
